// Oculus XR plugin (libOVRPlugin) games. Same mechanism as the VrApi adapter (olfx_vrapi.c): every ovrp_* import of
// a game is bound to a stub (olfx_ovrp_stubs.S, generated by scripts/gen_ovrp_stubs.py) that jumps into
// libolfx_ovrplugin.so, the OpenXR-backed OVRPlugin shim, loaded by Husk's linker the first time a game calls one.
// The game's own libOVRPlugin.so (which wants a Quest system service) is never used; the shim's xr* calls land in our
// OpenXR runtime.
//
// Local Meta Platform compatibility responses do not verify ownership.
#include <dlfcn.h>
#include <mach/mach.h>
#include <pthread.h>
#include <unistd.h>
#include <stdint.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include "../../../common/olfx_meta_stub.h"
#include "olfx_ovrp.h"
#include "olfx_xr_internal.h"

typedef struct tl_lib tl_lib;
extern tl_lib *tl_ld_load(const char *name);
extern int tl_ld_init(tl_lib *lib);
extern void *tl_ld_sym(tl_lib *lib, const char *name);
extern void tl_ld_add_search_dir(const char *dir);
extern void tl_ld_interpose(const char *name, void *fn);

#define MAXN 700
void *olfx_ovrp_tab[MAXN];
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static tl_lib *g_shim;
static int g_tried;

// ovrpFailure_Unsupported: used when the shim is not available, so the game sees "feature missing" and not a crash.
static int fail_stub(void) { return -1004; }

void *olfx_ovrp_resolve(int idx)
{
	pthread_mutex_lock(&g_mu);
	if (!g_tried) {
		g_tried = 1;
		g_shim = tl_ld_load("libolfx_ovrplugin.so");
		if (g_shim) { tl_ld_init(g_shim); OLFX_LOG("OVRPlugin shim loaded (Oculus XR plugin adapter)"); }
		else OLFX_LOG("OVRPlugin shim failed to load; ovrp_* calls will fail");
	}
	OLFX_LOG("OVRPlugin: first call %s", olfx_ovrp_names[idx]);     // device traces: which ovrp_* a game really uses, in order
	void *fn = g_shim ? tl_ld_sym(g_shim, olfx_ovrp_names[idx]) : NULL;
	if (!fn) { OLFX_LOG("OVRPlugin: %s not available", olfx_ovrp_names[idx]); fn = (void *)fail_stub; }
	olfx_ovrp_tab[idx] = fn;
	pthread_mutex_unlock(&g_mu);
	return fn;
}

// Trace of every ovrp_* call for the first few thousand calls (thread id + name), so a hang shows which call was the last one.
// The fast path in olfx_ovrp_stubs.S goes through here while olfx_ovrp_trace_n > 0.
int olfx_ovrp_gles_on;                       // set by the app before a game starts (settings: OpenGL ES VR, experimental)
static void olfx_hang_watch_start(void);
void olfx_ovrp_set_gles(int on) { olfx_ovrp_gles_on = on != 0; OLFX_LOG("OVRPlugin: OpenGL ES VR path %s", on ? "ON" : "off (flat mode)"); if (on) olfx_hang_watch_start(); }

// Hang sampler (OpenGL ES VR path only): 15 s and 35 s after the game starts it stops every thread for a moment, writes down where each
// one is (pc, lr and the frame-pointer chain), resumes them, and only then looks the addresses up and logs them. A game stuck at
// "alive: 1 frames" shows here which call every thread is waiting in.
extern const char *tl_ld_symbol_at(const void *addr, const char **lib, const void **base);
#define HW_MAXT 48
#define HW_MAXF 10
#define HW_STK 600
typedef struct { char name[24]; uintptr_t f[HW_MAXF]; int n; uintptr_t stk[HW_STK]; int ns; } hw_thread;
static hw_thread g_hw[HW_MAXT];
static void hw_sample(const char *label)
{
	mach_port_t self = mach_thread_self();
	thread_act_array_t th = NULL; mach_msg_type_number_t n = 0;
	if (task_threads(mach_task_self(), &th, &n) != KERN_SUCCESS) return;
	int out = 0;
	for (mach_msg_type_number_t i = 0; i < n && out < HW_MAXT; i++) {
		if (th[i] == self) continue;
		hw_thread *t = &g_hw[out]; memset(t, 0, sizeof *t);
		pthread_t pt = pthread_from_mach_thread_np(th[i]);
		if (pt) pthread_getname_np(pt, t->name, sizeof t->name);
		if (thread_suspend(th[i]) != KERN_SUCCESS) continue;
		arm_thread_state64_t st; mach_msg_type_number_t cnt = ARM_THREAD_STATE64_COUNT;
		if (thread_get_state(th[i], ARM_THREAD_STATE64, (thread_state_t)&st, &cnt) == KERN_SUCCESS) {
			t->f[t->n++] = (uintptr_t)arm_thread_state64_get_pc(st);
			t->f[t->n++] = (uintptr_t)arm_thread_state64_get_lr(st);
			if (!strncmp(t->name, "Unity", 5)) {   // raw stack words: guest code has no frame pointers, so scan them for return addresses
				uintptr_t sp = (uintptr_t)arm_thread_state64_get_sp(st); vm_size_t got = 0;
				if (vm_read_overwrite(mach_task_self(), sp, sizeof t->stk, (vm_address_t)t->stk, &got) == KERN_SUCCESS) t->ns = (int)(got / sizeof(uintptr_t));
			}
			uintptr_t fp = (uintptr_t)arm_thread_state64_get_fp(st);
			for (int k = 0; k < HW_MAXF - 2 && fp && !(fp & 7); k++) {
				uintptr_t rec[2]; vm_size_t got = 0;
				if (vm_read_overwrite(mach_task_self(), fp, sizeof rec, (vm_address_t)rec, &got) != KERN_SUCCESS || got != sizeof rec) break;
				if (rec[1]) t->f[t->n++] = rec[1];
				if (rec[0] <= fp) break;
				fp = rec[0];
			}
		}
		thread_resume(th[i]);
		out++;
	}
	for (mach_msg_type_number_t i = 0; i < n; i++) mach_port_deallocate(mach_task_self(), th[i]);
	vm_deallocate(mach_task_self(), (vm_address_t)th, n * sizeof(thread_t));
	OLFX_LOG("hang sampler (%s): %d threads", label, out);
	for (int i = 0; i < out; i++) {
		char line[1500]; int len = snprintf(line, sizeof line, "  thread '%s':", g_hw[i].name);
		for (int k = 0; k < g_hw[i].n && len < (int)sizeof line - 100; k++) {
			const char *lib = NULL; const void *base = NULL;
			const char *sym = tl_ld_symbol_at((const void *)g_hw[i].f[k], &lib, &base);
			Dl_info di;
			if (lib) len += snprintf(line + len, sizeof line - len, " %s %s+%#lx[abs %#lx];", lib, sym ? sym : "?", base ? (unsigned long)(g_hw[i].f[k] - (uintptr_t)base) : 0ul, (unsigned long)g_hw[i].f[k]);
			else if (dladdr((const void *)g_hw[i].f[k], &di) && di.dli_sname) len += snprintf(line + len, sizeof line - len, " %s;", di.dli_sname);
			else len += snprintf(line + len, sizeof line - len, " %#lx;", (unsigned long)g_hw[i].f[k]);
		}
		OLFX_LOG("%s", line);
		if (g_hw[i].ns > 0) {   // symbolise the stack words that point into a loaded guest library
			char sl[2600]; int sn = snprintf(sl, sizeof sl, "  stack scan of '%s':", g_hw[i].name); int hits = 0; uintptr_t last = 0;
			for (int k = 0; k < g_hw[i].ns && hits < 60 && sn < (int)sizeof sl - 120; k++) {
				uintptr_t w = g_hw[i].stk[k]; if (w < 0x100000000ul || w == last) continue;
				const char *lib = NULL; const void *base = NULL;
				const char *sym = tl_ld_symbol_at((const void *)w, &lib, &base);
				if (!lib || !base || (uintptr_t)base > w || w - (uintptr_t)base > 0x8000000) continue;
				const char *sh = strrchr(lib, '/'); sh = sh ? sh + 1 : lib;
				sn += snprintf(sl + sn, sizeof sl - sn, " %s+%#lx(%s)[abs %#lx];", sh, (unsigned long)(w - (uintptr_t)base), sym ? sym : "?", (unsigned long)w);
				// Write the loaded image of the Oculus plugin to Documents, so the code the thread waits in can be read offline.
				static int dumped;
				if (!dumped && !strcmp(sh, "libOculusXRPlugin.so")) {
					dumped = 1;
					const char *home = getenv("HOME"); char path[1024];
					snprintf(path, sizeof path, "%s/Documents/olfx-dump-libOculusXRPlugin.bin", home ? home : ".");
					FILE *f = fopen(path, "wb"); size_t total = 0;
					if (f) {
						static char buf[16384];
						for (uintptr_t off = 0; off < 0x80000; off += sizeof buf) {
							vm_size_t got = 0;
							if (vm_read_overwrite(mach_task_self(), (vm_address_t)((uintptr_t)base + off), sizeof buf, (vm_address_t)buf, &got) != KERN_SUCCESS || got == 0) memset(buf, 0, sizeof buf);
							fwrite(buf, 1, sizeof buf, f); total += sizeof buf;
						}
						fclose(f);
					}
					OLFX_LOG("dumped libOculusXRPlugin.so image (base %p, %zu bytes, wait at +%#lx) to %s", base, total, (unsigned long)(w - (uintptr_t)base), path);
				}
				last = w; hits++;
			}
			OLFX_LOG("%s", sl);
		}
	}
}
static void *hw_main(void *arg)
{
	(void)arg;
	sleep(15); hw_sample("15 s after the game was started");
	sleep(20); hw_sample("35 s after the game was started");
	return NULL;
}
static void olfx_hang_watch_start(void)
{
	pthread_t t; pthread_attr_t a; pthread_attr_init(&a); pthread_attr_setdetachstate(&a, PTHREAD_CREATE_DETACHED);
	pthread_create(&t, &a, hw_main, NULL);
}
int olfx_ovrp_trace_n = 4000;
void *olfx_ovrp_resolve_traced(int idx)
{
	int n = olfx_ovrp_trace_n;
	{ // the per-frame input/pose queries would use up the whole budget in a second: skip them
		const char *nm = olfx_ovrp_names[idx];
		if (strstr(nm, "GetNode") || strstr(nm, "GetController") || strstr(nm, "GetInitialized") || strstr(nm, "Present") ||
		    strstr(nm, "Update") || strstr(nm, "PollEvent") || strstr(nm, "Media_Get") || strstr(nm, "Haptics") || strstr(nm, "GetAppHas") ||
		    strstr(nm, "GetAppShould") || strstr(nm, "GetLocalTracking") || strstr(nm, "GetAudio") || strstr(nm, "GetPredicted"))
			n = 0;
	}
	if (n > 0) {
		olfx_ovrp_trace_n = n - 1;
		uint64_t tid = 0; pthread_threadid_np(NULL, &tid);
		OLFX_LOG("OVRPlugin: call %s [t%llu #%d]", olfx_ovrp_names[idx], (unsigned long long)tid, 4000 - n);
	}
	{   // who calls the display lifecycle functions: walk the guest frame chain
		const char *nm = olfx_ovrp_names[idx];
		static int budget = 60;
		if (budget > 0 && (strstr(nm, "Destroy") || strstr(nm, "SetupLayer") || strstr(nm, "EndFrame") || strstr(nm, "Shutdown") || strstr(nm, "Setup"))) {
			budget--;
			void **fp = (void **)__builtin_frame_address(1);
			char line[900]; int len = snprintf(line, sizeof line, "OVRPlugin: caller of %s:", nm);
			for (int k = 0; k < 8 && fp && ((uintptr_t)fp & 7) == 0 && (uintptr_t)fp > 0x100000000ull && len < 700; k++) {
				const void *lr = fp[1]; const char *lib = NULL; const void *base = NULL;
				const char *sym = tl_ld_symbol_at(lr, &lib, &base);
				len += snprintf(line + len, sizeof line - len, " %s %s+%#lx[abs %p];", lib ? lib : "?", sym ? sym : "?", base ? (unsigned long)((uintptr_t)lr - (uintptr_t)base) : 0ul, lr);
				void **nx = (void **)fp[0]; if (nx <= fp) break; fp = nx;
			}
			OLFX_LOG("%s", line);
		}
	}
	void *fn = olfx_ovrp_tab[idx];
	return fn ? fn : olfx_ovrp_resolve(idx);
}

// Compatibility responses are local; account, purchases and other Meta services are unavailable.
static int olfx_platform_init(const void *a, void *b, void *c) { (void)a; (void)b; (void)c; return 0; }
static int olfx_platform_init_opts(const void *a, void *b, void *c, void *o) { (void)o; return olfx_platform_init(a,b,c); }
static uint64_t olfx_platform_init_async(const void *a, void *b, void *c) { (void)a; (void)b; (void)c; return olfx_meta_init_async(); }
int olfx_take_entitlement_unavailable(void) { return 0; }
static uint64_t olfx_platform_default(void) { return 0; }
static int olfx_unity_init(const void *a) { (void)a; return 1; }
static uint64_t olfx_unity_init_async(const void *a) { return olfx_platform_init_async(a, NULL, NULL); }

void olfx_ovrp_install(const char *libdir)
{
	if (olfx_ovrp_count > MAXN) { OLFX_LOG("too many OVRPlugin exports"); return; }
	if (libdir) tl_ld_add_search_dir(libdir);
	for (int i = 0; i < olfx_ovrp_count; i++) tl_ld_interpose(olfx_ovrp_names[i], olfx_ovrp_stubs[i]);
	tl_ld_interpose("ovr_PlatformInitializeAndroid", (void *)olfx_platform_init);
	tl_ld_interpose("ovr_PlatformInitializeAndroidWithOptions", (void *)olfx_platform_init_opts);
	tl_ld_interpose("ovr_PlatformInitializeAndroidAsynchronous", (void *)olfx_platform_init_async);
	tl_ld_interpose("ovr_$default", (void *)olfx_platform_default);
	tl_ld_interpose("ovr_Entitlement_GetIsViewerEntitled", (void *)olfx_meta_entitlement);
	tl_ld_interpose("ovr_PopMessage", (void *)olfx_meta_pop);
	tl_ld_interpose("ovr_FreeMessage", (void *)olfx_meta_free);
	tl_ld_interpose("ovr_Message_GetRequestID", (void *)olfx_meta_id);
	tl_ld_interpose("ovr_Message_GetType", (void *)olfx_meta_type);
	tl_ld_interpose("ovr_Message_IsError", (void *)olfx_meta_error);
	tl_ld_interpose("ovr_Message_GetPlatformInitialize", (void *)olfx_meta_init_result);
	tl_ld_interpose("ovr_PlatformInitialize_GetResult", (void *)olfx_meta_result);
	tl_ld_interpose("ovr_UnityInitWrapper", (void *)olfx_unity_init);
	tl_ld_interpose("ovr_UnityInitWrapperAsynchronous", (void *)olfx_unity_init_async);
	OLFX_LOG("OVRPlugin: %d functions routed to the shim (dir %s)", olfx_ovrp_count, libdir ? libdir : "-");
}
